#include <iostream>
template <typename T>
class Shape {
public:
  virtual void draw() = 0; // Pure virtual function for runtime polymorphism
  virtual ~Shape() = default;
};

template <typename T>
class Circle : public Shape<T> {
public:
  void draw() override { std::cout << "Drawing Circle (Runtime Polymorphism)\n"; }
};

template <typename T>
struct StaticCircle {
  void draw() { std::cout << "Drawing Circle (Compile-Time Polymorphism)\n"; }
};
template <> struct StaticCircle<int> {void draw() { std::cout << "Drawing int Circle (Compile-Time Polymorphism)\n";}}

int main() {
  Shape<int>* circle_runtime = new Circle<int>();
  circle_runtime->draw();
  delete circle_runtime;
  StaticCircle<double> circle_compile; // Compile time polymorphism via template instantiation
  circle_compile.draw();
  StaticCircle<int> intCircle; // Compile-time polymorphism with specialization
  intCircle.draw();
  return 0;
}
